// Settling a charge takes the bank a moment. It remembers every payment it has charged,
// which is how it can tell when it is asked about one again
const SETTLE_MS = 400;
const charged = new Set();

// Busy, it turns every fifth charge it is asked for down without making it, and expects to
// be asked again later
const DECLINE_EVERY = 5;
let asked = 0;

export const metrics = { repeats: 'Count' };

export async function handle(request, { metric }) {
  const { pathname } = new URL(request.url);
  if (request.method !== 'POST' || pathname !== '/charges') {
    return new Response('Not found\n', { status: 404 });
  }
  const { payment, customer, amount } = await request.json();
  await new Promise((resolve) => setTimeout(resolve, SETTLE_MS));
  asked += 1;
  if (asked % DECLINE_EVERY === 0) {
    console.log(`turned down payment ${payment}, ask again later`);
    return Response.json({ error: 'Busy, try again later' }, { status: 503 });
  }
  if (charged.has(payment)) {
    metric('repeats', 1);
    console.log(`charged ${amount} to ${customer} again for payment ${payment}`);
  } else {
    charged.add(payment);
    console.log(`charged ${amount} to ${customer} for payment ${payment}`);
  }
  metric('payments charged', charged.size, 'None');
  return Response.json({ charged: amount });
}

