import express from 'express';
import { SendMessageCommand, SQSClient } from '@aws-sdk/client-sqs';

// Glass Garden gives every instance its own PORT, because they all share one machine here.
// In a real deployment they would each be on their own machine, and could all listen on the same port.
const port = Number(process.env.PORT);
if (!port) {
  throw new Error('PORT is not set');
}

// Named for the queue node it comes from, so connecting something else here would not change
// it. The endpoint and the credentials the SDK needs to reach the local AWS region arrive in
// the environment too, which is why the client below takes no arguments. The Config tab lists
// every variable this instance is launched with
const queueUrl = process.env.PAYMENTS_QUEUE_URL;
if (!queueUrl) {
  throw new Error('PAYMENTS_QUEUE_URL is not set. Connect this instance group to the Payments queue.');
}

const sqs = new SQSClient({});

// Three subscribers on the same monthly plan, so every payment is for the same amount. The
// sender numbers each delivery it makes and the subscribers take their turn in order, so
// delivery 7 is Grace paying 2500
const SUBSCRIBERS = ['Ada', 'Grace', 'Katherine'];
const AMOUNT = 2500;

const app = express();
app.use(express.json());

// The balancer asks for this before it sends any payments here, the way an ALB checks a target
// group. An instance that stops answering it is taken out of the rotation
app.get('/', (req, res) => {
  res.type('text/plain').send('ok\n');
});

// Answering quickly is the whole reason the queue is here: the
// sender gives up waiting long before a card can be charged
app.post('/payments', async (req, res) => {
  const payment = Number(req.body.payment);
  const customer = SUBSCRIBERS[payment % SUBSCRIBERS.length];

  await sqs.send(
    new SendMessageCommand({
      QueueUrl: queueUrl,
      MessageBody: JSON.stringify({ payment, customer, amount: AMOUNT })
    })
  );

  res.status(202).json({ status: 'queued' });
});

// Express hands a rejected handler here. This server is fine, the queue is not: an edge may
// have been removed, which the region answers with a message saying so
app.use((error, req, res, next) => {
  console.error('queue unavailable:', error.message);
  res.status(503).type('text/plain').send(`Queue unavailable: ${error.message}\n`);
});

app.listen(port, () => {
  console.log(`Server running on http://localhost:${port}`);
});

