// Named for the node it comes from, so connecting something else to this function leaves it
// alone. The Config tab lists every variable this function is launched with
const bank = process.env.BANK_URL;

// The local AWS region polls the queue on this function's behalf, exactly as the Lambda
// service does, and deletes a batch only once the handler returns. When the Bank turns a
// charge down, the error below fails the whole batch: the charges already made stand, and
// every payment in it comes back to be delivered again once the queue's visibility timeout
// runs out
export async function handler(event) {
  for (const record of event.Records) {
    const { payment, customer, amount } = JSON.parse(record.body);

    const response = await fetch(`${bank}/charges`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ payment, customer, amount })
    });
    if (!response.ok) {
      throw new Error(`The Bank answered ${response.status} for payment ${payment}`);
    }

    console.log(`payment ${payment}: charged ${amount} to ${customer}`);
  }
}
